export function performSafetyCheck(safetyCheckFunction: () => void, timeout: number): boolean {
  return new Promise<boolean>((resolve) => {
    const timeoutId = setTimeout(() => {
      console.error('Safety check timed out');
      resolve(false);
    }, timeout);

    try {
      const result = safetyCheckFunction();
      clearTimeout(timeoutId);
      resolve(result);
    } catch (error) {
      clearTimeout(timeoutId);
      console.error('Safety check failed:', error);
      resolve(false);
    }
  });
}

