export function sanitizeQuery(query: string): string {
  const regex = /^[-a-zA-Z0-9_/	 ]+$/; // Allow alphanumeric, underscore, slash, tab, and space
  const sanitizedQuery = query.replace(/[^-a-zA-Z0-9_/	 ]/g, '');
  return regex.test(sanitizedQuery) ? sanitizedQuery : '';
}

export function safeGrep(query: string, fileContent: string): string[] {
