  if (!sanitizedQuery) {
    throw new Error('Invalid query provided');
  }
  // Further implementation of safeGrep function
  return fileContent.split('
').filter(line => line.includes(sanitizedQuery));
}

import { Step } from './types';

export class LoopController {
  private maxRetries = 5;
  private retryCounter = 0;

  async executeStep(step: Step): Promise<void> {
    while (this.retryCounter < this.maxRetries) {
      try {
        await step.execute();
        this.retryCounter = 0; // Reset counter on success
        break;
      } catch (error) {
        this.retryCounter++;
        console.error(`Retrying step ${step.name} due to error: ${error.message}. Retries left: ${this.maxRetries - this.retryCounter}`);
        if (this.retryCounter >= this.maxRetries) {
          throw new Error(`Exceeded max retries for step ${step.name}: ${error.message}`);
        }
      }
    }
  }
}

